import json
from hypothesis import strategies as st


@st.composite
def gen(draw):
    n = draw(st.integers(1, 6))
    mode = draw(st.sampled_from(["random", "random", "equal", "sorted", "reverse"]))
    if mode == "equal":
        v = draw(st.integers(1, 10))
        nums = [v] * n
    elif mode == "sorted":
        nums = sorted(draw(st.lists(st.integers(1, 10), min_size=n, max_size=n)))
    elif mode == "reverse":
        nums = sorted(draw(st.lists(st.integers(1, 10), min_size=n, max_size=n)), reverse=True)
    else:
        nums = draw(st.lists(st.integers(1, 10), min_size=n, max_size=n))
    limit = draw(st.integers(1, 10))
    return f"{json.dumps(nums)}\n{limit}\n"


def validate(inp):
    lines = inp.strip("\n").split("\n")
    if len(lines) != 2:
        return False
    try:
        nums = json.loads(lines[0])
        limit = json.loads(lines[1])
    except Exception:
        return False
    if not isinstance(nums, list) or not (1 <= len(nums) <= 6):
        return False
    if not all(type(x) is int and 1 <= x <= 10 for x in nums):
        return False
    if type(limit) is not int or not (1 <= limit <= 10):
        return False
    # canonical formatting check
    if lines[0] != json.dumps(nums):
        return False
    return True


def ref(inp):
    lines = inp.strip("\n").split("\n")
    nums = tuple(json.loads(lines[0]))
    limit = json.loads(lines[1])
    n = len(nums)
    # Literal definition: explore every array reachable by allowed swaps.
    visited = {nums}
    stack = [nums]
    while stack:
        cur = stack.pop()
        for i in range(n):
            for j in range(i + 1, n):
                if abs(cur[i] - cur[j]) <= limit:
                    lst = list(cur)
                    lst[i], lst[j] = lst[j], lst[i]
                    nxt = tuple(lst)
                    if nxt not in visited:
                        visited.add(nxt)
                        stack.append(nxt)
    best = min(visited)
    return json.dumps(list(best))
